const crypto = require('crypto');
const secret = $env.AUTOMATION_API_SECRET;
const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!secret || !base) throw new Error('AUTOMATION_API_SECRET and CONVEX_SITE_URL must be set on the n8n container');
// Signature = HMAC-SHA256 over `${unixSeconds}.${METHOD}.${path}.${rawBody}`
const signed = (method, path, body) => {
  const ts = String(Math.floor(Date.now() / 1000));
  const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${method}.${path}.${body}`).digest('hex');
  return { url: base + path, ts, sig };
};

return [{ json: signed('GET', '/automation/overdue-loans', '') }];

const { loans } = $input.first().json;
const today = new Date().toISOString().slice(0, 10);
const items = [];

for (const loan of loans || []) {
  // A manual re-run on the same day must not remind people twice.
  if (loan.lastReminderAt && new Date(loan.lastReminderAt).toISOString().slice(0, 10) === today) continue;

  const clean = (s) => String(s ?? '').replace(/[\r\n]+/g, ' ').trim().slice(0, 80);
  const days = loan.daysOverdue;
  items.push({ json: {
    loanId: loan.loanId,
    today,
    message: {
      subject: `Reminder: please return the ${clean(loan.toolName)}`,
      text: `Hi ${clean(loan.borrowerName) || 'there'}, the ${clean(loan.toolName)} was due on ${loan.dueDate} and is ${days} day${days === 1 ? '' : 's'} overdue. Please return it to its owner as soon as you can.`,
    },
  } });
}
return items;

// Notification channel. Default: log it (visible in the n8n execution).
// If NOTIFY_WEBHOOK_URL is set (Slack / Mattermost / Discord-compatible), also POST it there.
const deliver = async (message) => {
  console.log(`[lendloop notification] ${message.subject} :: ${message.text.replace(/\n/g, ' ')}`);
  const url = $env.NOTIFY_WEBHOOK_URL;
  if (!url) return 'log';
  await this.helpers.httpRequest({
    method: 'POST', url, json: true, timeout: 8000,
    body: { text: `*${message.subject}*\n${message.text}`, content: `**${message.subject}**\n${message.text}` },
  });
  return 'webhook';
};

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const out = [];

// One loan failing must not stop the others, so errors are caught per item and reported downstream.
for (const item of $input.all()) {
  const { loanId, today, message } = item.json;
  let channel = null, error = null;
  for (let attempt = 1; attempt <= 3 && channel === null; attempt++) {
    try { channel = await deliver(message); }
    catch (e) { error = String(e.message || e).slice(0, 200); if (attempt < 3) await sleep(1500 * attempt); }
  }
  out.push({ json: {
    loanId,
    channel: channel ?? 'none',
    status: channel ? 'sent' : 'failed',
    error: channel ? null : error,
    // Success and failure get different keys so that a failure never blocks a later successful reminder.
    idempotencyKey: `${loanId}:${today}${channel ? '' : ':failed'}`,
  } });
}
return out;

