  const { loanId, idempotencyKey, channel, status, error } = item.json;
  const body = JSON.stringify({ loanId, idempotencyKey, channel, status });
  return { json: { ...signed('POST', '/automation/reminders', body), body, status, error } };
});

const failed = $('Send reminders').all().filter((i) => i.json.status === 'failed');
if (failed.length > 0) {
  throw new Error(`${failed.length} reminder(s) could not be delivered: ${failed.map((i) => `${i.json.loanId} (${i.json.error})`).join('; ')}`);
}
return [{ json: { reminded: $('Send reminders').all().length } }];
